#!/usr/bin/env python3
"""AMBER WORLD CLASS V0.7 source-generated animations.
Original source is zlib-compressed below to keep connector transfer reliable.
To obtain the readable Python, run: python tools/build_sprite_full_v07.py --extract
Requires Pillow for PNG generation. Only writes public/assets/v07/.
"""
from __future__ import annotations
import base64,zlib,sys
_SOURCE=(" ")
source=zlib.decompress(base64.b64decode(_SOURCE)).decode('utf-8')
if '--extract' in sys.argv:
    print(source)
else:
    exec(compile(source,__file__,'exec'),{'__file__':__file__,'__name__':'__main__'})
